	FLAC__ASSERT(0 != decoder->private_);
	FLAC__ASSERT(0 != decoder->protected_);
	FLAC__ASSERT((unsigned)type <= FLAC__MAX_METADATA_TYPE_CODE);
 /* double protection */
 if((unsigned)type > FLAC__MAX_METADATA_TYPE_CODE)
