    EXPECT_TRUE(lim->Apply(b, start_time + TimeDelta::FromSeconds(20 + m)));
    EXPECT_FALSE(b->has_tokens());
    EXPECT_TRUE(lim->Apply(b, start_time + TimeDelta::FromSeconds(50 + m)));
    EXPECT_FALSE(b->has_tokens());
  }
}

