static void CheckAllowedDomainsHeader(
    const std::string& allowed_domain,
    const std::map<GURL, net::HttpRequestHeaders>& urls_requested,
    const GURL& url) {
  auto iter = urls_requested.find(url);
  ASSERT_TRUE(iter != urls_requested.end());
  if (allowed_domain.empty()) {
    EXPECT_TRUE(
        !iter->second.HasHeader(safe_search_util::kGoogleAppsAllowedDomains));
    return;
  }

  std::string header;
  iter->second.GetHeader(safe_search_util::kGoogleAppsAllowedDomains,
                         &header);
  EXPECT_EQ(header, allowed_domain);
}

void BaseFetchContext::AddAdditionalRequestHeaders(ResourceRequest& request,
                                                   FetchResourceType type) {
  bool is_main_resource = type == kFetchMainResource;
  if (!is_main_resource) {
    if (!request.DidSetHTTPReferrer()) {
      request.SetHTTPReferrer(SecurityPolicy::GenerateReferrer(
          GetReferrerPolicy(), request.Url(), GetOutgoingReferrer()));
      request.AddHTTPOriginIfNeeded(GetSecurityOrigin());
    } else {
      DCHECK_EQ(SecurityPolicy::GenerateReferrer(request.GetReferrerPolicy(),
                                                 request.Url(),
                                                 request.HttpReferrer())
                    .referrer,
                request.HttpReferrer());
      request.AddHTTPOriginIfNeeded(request.HttpReferrer());
    }
  }

  auto address_space = GetAddressSpace();
  if (address_space)
    request.SetExternalRequestStateFromRequestorAddressSpace(*address_space);
}

