    std::vector<iovec> iov = {
 {NULL, 0}, // reserved for the eventual addition of a NLMSG_HDR
 {&spiInfo, 0}, // main userspi_info struct
 {kPadBytes, 0}, // up to NLMSG_ALIGNTO pad bytes of padding
 };

